                    sr[j - 1][m] - sr[j - 1][k - 1] +
                    s[j - 1][m] - s[j - 1][k]
                ) % modulo;
            }
        }

        computasuma(i);
    }

    total = (total + modulo) % modulo;
    cout << total << endl;
